-- Retrouver les anomalies que la base n'a plus — et les remettre.
-- Produit par outils/retrouver_les_anomalies_disparues.py — 674 lignes du tableau.
--
-- Ne touche à RIEN de ce qui existe : ni les anomalies présentes,
-- ni les photos, ni le fil, ni le stock, ni les dossiers bouteille.
-- Il ne lit que l'absence — un identifiant que le tableau porte et
-- que la table n'a pas — et remet la ligne manquante avec ce que le
-- tableau sait d'elle.
--
-- À jouer APRÈS avoir lu 1_ce_qui_manque.sql, d'un bloc, dans
-- l'éditeur SQL de Supabase. Le résultat affiché dit ce qui a été
-- remis.

begin;

-- L'état d'une anomalie vient du tableau, pas du recalcul des avis.
alter table validations disable trigger tg_validation_maj_anomalie;

-- Le tableau, tel qu'il est. Une ligne par anomalie.
create temporary table tableau (
  sharepoint_id  int primary key,
  lieu           text,
  libelle        text,
  canonique      text,
  type_code      text,
  statut         text,
  declare_le     date,
  cloture_le     date,
  constate_par   text,
  saisie_par     text,
  commentaire    text,
  fait_le        date,
  par            text,
  prestataire    text,
  externe        boolean,
  verifie_le     date,
  verifie_par    text,
  produit        text,
  quantite       numeric
) on commit drop;

-- 1. Ce qui manque. Une ligne ici = une anomalie disparue de la base.
create temporary table disparues on commit drop as
select t.* from tableau t
 where not exists (select 1 from anomalies a
        where a.sharepoint_id = t.sharepoint_id);

-- Et voici ce qui manque. C'est le résultat que Supabase affiche.
select sharepoint_id as "n° d'origine", lieu, libelle as "libellé",
       declare_le as "déclarée le", statut,
       fait_le as "faite le", coalesce(nullif(par,''), prestataire) as "par",
       nullif(commentaire, '') as "commentaire du tableau"
  from disparues order by declare_le, sharepoint_id;

-- 2. L'anomalie revient : son lieu, son libellé, son métier, son
--    rattachement au catalogue — sans lui, le comptage des
--    récurrences (règle 8) perdrait cette ligne.
                       description, statut, constate_par, saisie_par,
                       declare_le, cloture_le)
select d.sharepoint_id, e.id, c.id, ty.id, d.libelle,
       d.statut::statut_anomalie, uc.id, coalesce(us.id, uc.id),
       d.declare_le::timestamptz, d.cloture_le::timestamptz
  from disparues d
  join emplacements e on e.code = d.lieu
  left join catalogue_anomalies c on c.libelle = d.canonique
  left join types_intervention ty on ty.code = nullif(d.type_code, '')
  left join utilisateurs uc on lower(uc.nom) = lower(d.constate_par)
  left join utilisateurs us on lower(us.nom) = lower(d.saisie_par)
 on conflict (sharepoint_id) do nothing;

-- Le commentaire d'origine : c'est un propos, il a sa place au fil.
select a.id, d.commentaire, 'utilisateur', u.id, d.declare_le::timestamptz
  from disparues d
  join anomalies a on a.sharepoint_id = d.sharepoint_id
  left join utilisateurs u on lower(u.nom) = lower(d.constate_par)
 where d.commentaire <> ''
   and not exists (select 1 from commentaires cm
        where cm.anomalie_id = a.id and cm.texte = d.commentaire);

-- 3. Le passage : qui est venu, quel jour. La tournée se retrouve
--    plus bas, par fn_regrouper_les_passages().
                           prestataire_id, date_intervention, cree_le)
select a.id, null,
       case when d.externe then null else u.id end,
       case when d.externe then p.id else null end,
       d.fait_le, d.fait_le::timestamptz
  from disparues d
  join anomalies a on a.sharepoint_id = d.sharepoint_id
  left join utilisateurs u on lower(u.nom) = lower(d.par)
  left join prestataires p on lower(p.nom) = lower(d.prestataire)
 where d.fait_le is not null
   and not exists (select 1 from interventions i where i.anomalie_id = a.id);

-- 4. Les deux avis, chacun à sa date. Le refus d'une gouvernante
--    n'efface jamais l'avis du technicien (règle 3) : ils coexistent.
select i.id, 'technicien', 'fait',
       case when d.externe then null else u.id end, d.fait_le::timestamptz
  from disparues d
  join anomalies a on a.sharepoint_id = d.sharepoint_id
  join interventions i on i.anomalie_id = a.id
  left join utilisateurs u on lower(u.nom) = lower(d.par)
 where d.fait_le is not null
   and not exists (select 1 from validations v
        where v.intervention_id = i.id and v.acteur = 'technicien');

select i.id, 'gouvernante', 'validee', u.id, d.verifie_le::timestamptz
  from disparues d
  join anomalies a on a.sharepoint_id = d.sharepoint_id
  join interventions i on i.anomalie_id = a.id
  left join utilisateurs u on lower(u.nom) = lower(d.verifie_par)
 where d.verifie_le is not null
   and not exists (select 1 from validations v
        where v.intervention_id = i.id and v.acteur = 'gouvernante');

-- 5. Le matériel. Supprimer une anomalie ne rend pas ce qu'elle a
--    sorti : le mouvement reste en place, seulement détaché
--    (`intervention_id` à nul) — la pièce a bien quitté l'étagère.
--    On le RACCROCHE donc, on n'en crée pas un second : ce serait
--    sortir deux fois la même pièce.
--
--    Le rapprochement se fait sur le PRODUIT et le LIEU, pas sur le
--    commentaire (celui de la reprise porte le texte du tableau,
--    celui de l'application « Intervention — … ») et pas sur la seule
--    égalité stricte des dates : le tableau nettoyé a corrigé des jours
--    et des mois inversés (règle 16sexies), et le mouvement resté en
--    base peut encore porter l'ancienne date — le 03/05 s'y lit
--    03/05 à l'envers, soit 59 jours d'écart. On accepte donc les
--    DEUX lectures de la même date, et elles seules : une fenêtre de
--    tolérance attraperait un mouvement voisin qui n'a rien à voir.
--    Un seul mouvement par intervention (`limit 1`).
create temporary table raccroches on commit drop as
select i.id as intervention_id, pick.id as mouvement_id,
       d.sharepoint_id, d.fait_le, pick.date_mouvement::date as date_en_base
  from disparues d
  join anomalies a     on a.sharepoint_id = d.sharepoint_id
  join interventions i on i.anomalie_id = a.id
  join produits pr     on pr.designation = d.produit
  join lateral (
    select mm.id, mm.date_mouvement from mouvements_stock mm
     where mm.intervention_id is null
       and mm.produit_id = pr.id
       and mm.type = 'sortie'
       and mm.emplacement_id is not distinct from a.emplacement_id
       and mm.date_mouvement::date >= date '2025-01-01'
       and (mm.date_mouvement::date = d.fait_le
         or (extract(day from d.fait_le) <= 12
             and mm.date_mouvement::date = make_date(
                   extract(year  from d.fait_le)::int,
                   extract(day   from d.fait_le)::int,
                   extract(month from d.fait_le)::int)))
     order by abs(mm.date_mouvement::date - d.fait_le), mm.id limit 1) pick on true
 where d.produit <> '' and d.fait_le is not null;

update mouvements_stock m set intervention_id = c.intervention_id
  from raccroches c where m.id = c.mouvement_id;

-- Un mouvement raccroché sous une autre date, à relire : le
-- rapprochement est probable, il n'est pas certain.
select sharepoint_id as "n° d'origine", fait_le as "le tableau dit",
       date_en_base as "le mouvement portait"
  from raccroches where date_en_base is distinct from fait_le;

-- Et seulement s'il n'y en avait aucun à raccrocher, on le recrée.
                             prestataire_id, emplacement_id, intervention_id,
                             date_mouvement, commentaire)
select pr.id, 'sortie', -greatest(coalesce(d.quantite, 1), 1),
       case when d.externe then null else u.id end,
       case when d.externe then p.id else null end,
       a.emplacement_id, i.id, d.fait_le::timestamptz,
       'Intervention — ' || a.description
  from disparues d
  join anomalies a on a.sharepoint_id = d.sharepoint_id
  join interventions i on i.anomalie_id = a.id
  join produits pr on pr.designation = d.produit
  left join utilisateurs u on lower(u.nom) = lower(d.par)
  left join prestataires p on lower(p.nom) = lower(d.prestataire)
 where d.produit <> '' and d.fait_le is not null
   and not exists (select 1 from mouvements_stock m
        where m.intervention_id = i.id and m.produit_id = pr.id);

-- 6. L'intervention rejoint le passage de son jour et de son
--    intervenant, qui se crée s'il n'existait pas.
select * from fn_regrouper_les_passages();

alter table validations enable trigger tg_validation_maj_anomalie;

-- 7. Ce qui a été remis, pour vérifier avant de valider.
select a.sharepoint_id as "n° d'origine", e.code as lieu,
       a.description as "libellé", a.statut,
       a.declare_le::date as "déclarée le",
       i.date_intervention as "faite le",
       coalesce(u.nom, p.nom) as "par",
       t.reference as "passage",
       (select count(*) from commentaires cm where cm.anomalie_id = a.id)
         as "mots au fil",
       (select count(*) from mouvements_stock m
         where m.intervention_id = i.id) as "sorties de stock"
  from disparues d
  join anomalies a on a.sharepoint_id = d.sharepoint_id
  join emplacements e on e.id = a.emplacement_id
  left join interventions i on i.anomalie_id = a.id
  left join tournees t on t.id = i.tournee_id
  left join utilisateurs u on u.id = i.technicien_id
  left join prestataires p on p.id = i.prestataire_id
 order by a.declare_le;

-- Relire ci-dessus, puis :
commit;
-- (ou `rollback;` si quelque chose ne va pas — rien n'aura bougé.)
